1	/**
2	 * Default implementation of AuthBrokerFactory
3	 * Implements unified broker creation logic according to UNIFIED_BROKER_LOGIC.md
4	 *
5	 * Key principles:
6	 * - One broker per destination (key = destination name or 'default')
7	 * - Default broker created at startup based on CLI args and .env file presence
8	 * - Shared stores for destinations with same directory and type
9	 */
10	
11	import * as fs from 'node:fs';
12	import * as path from 'node:path';
13	import { AuthBroker } from '@babamba2/mcp-abap-adt-auth-broker';
14	import { AuthorizationCodeProvider } from '@babamba2/mcp-abap-adt-auth-providers';
15	import {
16	  AbapServiceKeyStore,
17	  AbapSessionStore,
18	  BtpServiceKeyStore,
19	  BtpSessionStore,
20	  EnvFileSessionStore,
21	  SafeAbapSessionStore,
22	  SafeBtpSessionStore,
23	} from '@babamba2/mcp-abap-adt-auth-stores';
24	import type {
25	  IAuthorizationConfig,
26	  IConnectionConfig,
27	  ILogger,
28	  IServiceKeyStore,
29	  ISessionStore,
30	  ITokenProvider,
31	  ITokenResult,
32	} from '@babamba2/mcp-abap-adt-interfaces';
33	import { defaultLogger } from '@babamba2/mcp-abap-adt-logger';
34	import { resolveSecret } from '../secrets';
35	import { detectStoreType } from '../stores';
36	import { getPlatformPaths } from '../stores/platformPaths';
37	import type { IAuthBrokerFactory } from './IAuthBrokerFactory.js';
38	import type { IAuthBrokerFactoryConfig } from './IAuthBrokerFactoryConfig.js';
39	
40	/**
41	 * Default implementation of IAuthBrokerFactory
42	 */
43	export class AuthBrokerFactory implements IAuthBrokerFactory {
44	  // Map of brokers: key = destination name (or 'default' for default broker)
45	  private authBrokers = new Map<string, AuthBroker>();
46	
47	  // Shared stores - one per store type and directory
48	  // Key: `${storeType}::${serviceKeysDir}::${sessionsDir}::${unsafe}`
49	  private sharedStores = new Map<
50	    string,
51	    { serviceKeyStore?: IServiceKeyStore; sessionStore: ISessionStore }
52	  >();
53	
54	  private config: IAuthBrokerFactoryConfig;
55	  private defaultBrokerInitialized = false;
56	
57	  constructor(config: IAuthBrokerFactoryConfig) {
58	    this.config = config;
59	  }
60	
61	  /**
62	   * Get transport type from config
63	   */
64	  private getTransportType(): string {
65	    return this.config.transportType;
66	  }
67	
68	  /**
69	   * Check if transport type supports AuthBroker
70	   */
71	  private isTransportSupported(): boolean {
72	    const transportType = this.getTransportType();
73	    if (!transportType) return false;
74	    return (
75	      transportType === 'streamable-http' ||
76	      transportType === 'http' ||
77	      transportType === 'stdio' ||
78	      transportType === 'sse'
79	    );
80	  }
81	
82	  /**
83	   * Initialize default broker based on CLI args and .env file presence
84	   * Called once at server startup
85	   *
86	   * Creates default broker ('default' key) according to unified logic:
87	   * 1. --mcp=destination → default broker with serviceKeyStore for destination
88	   * 2. --env=path → default broker with sessionStore from path (no serviceKeyStore)
89	   * 3. stdio/sse + .env in current folder + NOT --auth-broker → default broker with sessionStore (no serviceKeyStore)
90	   * 4. Other cases → default broker NOT created
91	   */
92	  async initializeDefaultBroker(): Promise<void> {
93	    if (this.defaultBrokerInitialized) {
94	      return; // Already initialized
95	    }
96	
97	    if (!this.isTransportSupported()) {
98	      return;
99	    }
100	
101	    // Only use logger if explicitly provided (no fallback to defaultLogger)
102	    // This prevents unwanted logging when DEBUG variables are not set
103	    const logger = this.config.logger;
104	    const defaultMcpDestination = this.config.defaultMcpDestination;
105	    const envFilePath = this.config.envFilePath;
106	    const useAuthBroker =
107	      this.config.useAuthBroker !== undefined
108	        ? this.config.useAuthBroker
109	        : !!this.config.defaultMcpDestination; // If --mcp is set, use auth-broker
110	    const unsafe = this.config.unsafe || false;
111	    const transportType = this.getTransportType();
112	    const isStdio = transportType === 'stdio';
113	    const isSse = transportType === 'sse';
114	    const isHttp = transportType === 'http';
115	
116	    logger?.debug('[BrokerFactory] initializeDefaultBroker called', {
117	      type: 'BROKER_INIT_START',
118	      defaultMcpDestination,
119	      envFilePath,
120	      useAuthBroker,
121	      transportType,
122	      isStdio,
123	      isSse,
124	      isHttp,
125	    });
126	    const customPath = this.config.authBrokerPath
127	      ? path.resolve(this.config.authBrokerPath)
128	      : undefined;
129	
130	    // Check if .env exists in current directory
131	    const cwdEnvPath = path.resolve(process.cwd(), '.env');
132	    const hasCwdEnv = fs.existsSync(cwdEnvPath);
133	
134	    // Determine if we should create default broker
135	    let shouldCreateDefault = false;
136	    let defaultBrokerConfig: {
137	      hasServiceKeyStore: boolean;
138	      serviceKeyDestination?: string;
139	      sessionStorePath: string;
140	      storeType: 'abap' | 'btp';
141	      envFileToLoad?: string; // Track which .env file to load
142	      useEnvFileStore?: boolean; // Use EnvFileSessionStore directly
143	    } | null = null;
144	
145	    // Variant 1: --mcp=destination specified
146	    if (defaultMcpDestination) {
147	      shouldCreateDefault = true;
148	      const serviceKeysPaths = getPlatformPaths(customPath, 'service-keys');
149	      const sessionsPaths = getPlatformPaths(customPath, 'sessions');
150	      const serviceKeysDir = serviceKeysPaths[0];
151	      const sessionsDir = sessionsPaths[0];
152	
153	      const detected = await detectStoreType(
154	        serviceKeysDir,
155	        defaultMcpDestination,
156	      );
157	
158	      defaultBrokerConfig = {
159	        hasServiceKeyStore: true,
160	        serviceKeyDestination: defaultMcpDestination,
161	        sessionStorePath: sessionsDir,
162	        storeType: detected.storeType,
163	      };
164	    }
165	    // Variant 2: --env=path specified (stdio/sse/http)
166	    // Use EnvFileSessionStore directly - no need for separate session store
167	    else if (envFilePath && (isStdio || isSse || isHttp)) {
168	      shouldCreateDefault = true;
169	      logger?.debug('Variant 2: --env specified, using EnvFileSessionStore', {
170	        envFilePath,
171	        isStdio,
172	        isSse,
173	        isHttp,
174	      });
175	
176	      defaultBrokerConfig = {
177	        hasServiceKeyStore: false,
178	        sessionStorePath: '', // Not used with EnvFileSessionStore
179	        storeType: 'abap', // Default, not used with EnvFileSessionStore
180	        envFileToLoad: envFilePath,
181	        useEnvFileStore: true, // Flag to use EnvFileSessionStore
182	      };
183	    }
184	    // Variant 3: stdio/sse/http + .env in current folder + NOT --auth-broker
185	    else if ((isStdio || isSse || isHttp) && hasCwdEnv && !useAuthBroker) {
186	      shouldCreateDefault = true;
187	      const serviceKeysPaths = getPlatformPaths(process.cwd(), 'service-keys');
188	      const sessionsPaths = getPlatformPaths(process.cwd(), 'sessions');
189	      const serviceKeysDir = serviceKeysPaths[0];
190	      const sessionsDir = sessionsPaths[0];
191	
192	      const detected = await detectStoreType(serviceKeysDir);
193	
194	      defaultBrokerConfig = {
195	        hasServiceKeyStore: false,
196	        sessionStorePath: sessionsDir,
197	        storeType: detected.storeType,
198	        envFileToLoad: cwdEnvPath, // Use .env from current directory
199	      };
200	    }
201	
202	    if (shouldCreateDefault && defaultBrokerConfig) {
203	      logger?.debug('Creating default broker', {
204	        shouldCreateDefault,
205	        hasConfig: !!defaultBrokerConfig,
206	      });
207	      try {
208	        logger?.debug('Initializing default broker', {
209	          type: 'DEFAULT_BROKER_INIT_START',
210	          hasServiceKeyStore: defaultBrokerConfig.hasServiceKeyStore,
211	          serviceKeyDestination: defaultBrokerConfig.serviceKeyDestination,
212	          sessionStorePath: defaultBrokerConfig.sessionStorePath,
213	          storeType: defaultBrokerConfig.storeType,
214	          useEnvFileStore: defaultBrokerConfig.useEnvFileStore,
215	        });
216	
217	        // Variant 2: Use EnvFileSessionStore directly
218	        if (
219	          defaultBrokerConfig.useEnvFileStore &&
220	          defaultBrokerConfig.envFileToLoad
221	        ) {
222	          await this.createBrokerWithEnvFileStore(
223	            'default',
224	            defaultBrokerConfig.envFileToLoad,
225	            logger,
226	          );
227	        } else {
228	          // Variant 1 and 3: Use standard stores
229	          await this.createBrokerForDestination(
230	            'default',
231	            defaultBrokerConfig.hasServiceKeyStore,
232	            defaultBrokerConfig.serviceKeyDestination,
233	            defaultBrokerConfig.sessionStorePath,
234	            defaultBrokerConfig.storeType,
235	            unsafe,
236	          );
237	
238	          // Load .env file into session store for Variant 3 (cwd .env)
239	          if (
240	            !defaultBrokerConfig.hasServiceKeyStore &&
241	            defaultBrokerConfig.envFileToLoad
242	          ) {
243	            const broker = this.authBrokers.get('default');
244	            if (broker) {
245	              try {
246	                await this.loadEnvFileIntoSessionStore(
247	                  defaultBrokerConfig.envFileToLoad,
248	                  'default',
249	                  broker,
250	                  logger,
251	                );
252	              } catch (error) {
253	                logger?.debug('Failed to load .env file into session store', {
254	                  type: 'ENV_LOAD_FAILED',
255	                  envFilePath: defaultBrokerConfig.envFileToLoad,
256	                  error: error instanceof Error ? error.message : String(error),
257	                });
258	                throw error;
259	              }
260	            }
261	          }
262	        }
263	
264	        this.defaultBrokerInitialized = true;
265	
266	        logger?.debug('Default broker initialized', {
267	          type: 'DEFAULT_BROKER_INIT_SUCCESS',
268	          hasServiceKeyStore: defaultBrokerConfig.hasServiceKeyStore,
269	          serviceKeyDestination: defaultBrokerConfig.serviceKeyDestination,
270	          hasEnvFile:
271	            !defaultBrokerConfig.hasServiceKeyStore &&
272	            !!defaultBrokerConfig.envFileToLoad,
273	          envFilePath: defaultBrokerConfig.envFileToLoad,
274	          useEnvFileStore: defaultBrokerConfig.useEnvFileStore,
275	        });
276	      } catch (error) {
277	        logger?.debug('Failed to initialize default broker', {
278	          type: 'DEFAULT_BROKER_INIT_FAILED',
279	          error: error instanceof Error ? error.message : String(error),
280	        });
281	        // Don't throw - server can still work without default broker
282	      }
283	    } else {
284	      logger?.debug('Default broker not created (no conditions met)', {
285	        type: 'DEFAULT_BROKER_NOT_CREATED',
286	        hasMcpDestination: !!defaultMcpDestination,
287	        hasEnvFilePath: !!envFilePath,
288	        isStdio,
289	        isSse,
290	        hasCwdEnv,
291	        useAuthBroker,
292	      });
293	    }
294	
295	    this.defaultBrokerInitialized = true; // Mark as initialized even if not created
296	  }
297	
298	  /**
299	   * Get default broker (if initialized)
300	   */
301	  getDefaultBroker(): AuthBroker | undefined {
302	    return this.authBrokers.get('default') || undefined;
303	  }
304	
305	  /**
306	   * Get or create AuthBroker for specific destination
307	   * For HTTP/SSE: called when destination is specified in headers
308	   * For stdio: called to get default broker
309	   */
310	  async getOrCreateAuthBroker(
311	    destination?: string,
312	    _clientKey?: string,
313	  ): Promise<AuthBroker | undefined> {
314	    if (!this.isTransportSupported()) {
315	      return undefined;
316	    }
317	
318	    // If no destination specified, try to get default broker
319	    if (!destination) {
320	      // Ensure default broker is initialized
321	      if (!this.defaultBrokerInitialized) {
322	        await this.initializeDefaultBroker();
323	      }
324	      return this.getDefaultBroker();
325	    }
326	
327	    // Special case: if destination is 'default', return default broker (don't create new one)
328	    if (destination === 'default') {
329	      // Ensure default broker is initialized
330	      if (!this.defaultBrokerInitialized) {
331	        await this.initializeDefaultBroker();
332	      }
333	      return this.getDefaultBroker();
334	    }
335	
336	    // Get or create broker for specific destination
337	    if (!this.authBrokers.has(destination)) {
338	      // Only use logger if explicitly provided (no fallback to defaultLogger)
339	      // This prevents unwanted logging when DEBUG variables are not set
340	      const logger = this.config.logger;
341	      const unsafe = this.config.unsafe || false;
342	      const customPath = this.config.authBrokerPath
343	        ? path.resolve(this.config.authBrokerPath)
344	        : undefined;
345	
346	      const serviceKeysPaths = getPlatformPaths(customPath, 'service-keys');
347	      const sessionsPaths = getPlatformPaths(customPath, 'sessions');
348	      const serviceKeysDir = serviceKeysPaths[0];
349	      const sessionsDir = sessionsPaths[0];
350	
351	      const detected = await detectStoreType(serviceKeysDir, destination);
352	
353	      try {
354	        await this.createBrokerForDestination(
355	          destination,
356	          true, // Always create serviceKeyStore for specific destination
357	          destination,
358	          sessionsDir,
359	          detected.storeType,
360	          unsafe,
361	        );
362	      } catch (error) {
363	        logger?.debug('Failed to create AuthBroker for destination', {
364	          type: 'AUTH_BROKER_CREATE_FAILED',
365	          destination,
366	          error: error instanceof Error ? error.message : String(error),
367	        });
368	        return undefined;
369	      }
370	    }
371	
372	    return this.authBrokers.get(destination) || undefined;
373	  }
374	
375	  /**
376	   * Create broker for specific destination
377	   * Internal method used by both initializeDefaultBroker and getOrCreateAuthBroker
378	   */
379	  private async createBrokerForDestination(
380	    brokerKey: string,
381	    hasServiceKeyStore: boolean,
382	    serviceKeyDestination: string | undefined,
383	    sessionsDir: string,
384	    storeType: 'abap' | 'btp',
385	    unsafe: boolean,
386	  ): Promise<void> {
387	    // Only use logger if explicitly provided (no fallback to defaultLogger)
388	    // This prevents unwanted logging when DEBUG variables are not set
389	    const logger = this.config.logger;
390	    // Only use specific loggers if DEBUG variables are set, no fallback
391	    const storeLogger = this.config.storeLogger;
392	    const _providerLogger = this.config.providerLogger;
393	    const brokerLogger = this.config.brokerLogger;
394	    const customPath = this.config.authBrokerPath
395	      ? path.resolve(this.config.authBrokerPath)
396	      : undefined;
397	
398	    const serviceKeysPaths = getPlatformPaths(customPath, 'service-keys');
399	    const serviceKeysDir = serviceKeysPaths[0];
400	
401	    // Get or create shared stores
402	    const storeKey = `${storeType}::${serviceKeysDir}::${sessionsDir}::${unsafe}`;
403	    let stores = this.sharedStores.get(storeKey);
404	
405	    if (!stores) {
406	      // Create new shared stores
407	      if (unsafe) {
408	        switch (storeType) {
409	          case 'abap':
410	            stores = {
411	              serviceKeyStore: hasServiceKeyStore
412	                ? new AbapServiceKeyStore(serviceKeysDir, storeLogger)
413	                : undefined,
414	              sessionStore: new AbapSessionStore(sessionsDir, storeLogger),
415	            };
416	            break;
417	          case 'btp':
418	            stores = {
419	              serviceKeyStore: hasServiceKeyStore
420	                ? new BtpServiceKeyStore(serviceKeysDir, storeLogger)
421	                : undefined,
422	              sessionStore: new BtpSessionStore(sessionsDir, '', storeLogger),
423	            };
424	            break;
425	        }
426	      } else {
427	        switch (storeType) {
428	          case 'abap':
429	            // Use safe in-memory store to avoid stale/locked files in ~/.config
430	            stores = {
431	              serviceKeyStore: hasServiceKeyStore
432	                ? new AbapServiceKeyStore(serviceKeysDir, storeLogger)
433	                : undefined,
434	              sessionStore: new SafeAbapSessionStore(storeLogger, undefined),
435	            };
436	            break;
437	          case 'btp':
438	            stores = {
439	              serviceKeyStore: hasServiceKeyStore
440	                ? new BtpServiceKeyStore(serviceKeysDir, storeLogger)
441	                : undefined,
442	              sessionStore: new SafeBtpSessionStore('', storeLogger),
443	            };
444	            break;
445	        }
446	      }
447	
448	      this.sharedStores.set(storeKey, stores);
449	
450	      logger?.debug('Created shared stores', {
451	        type: 'SHARED_STORES_CREATED',
452	        storeKey,
453	        storeType,
454	        hasServiceKeyStore,
455	        serviceKeysDir,
456	        sessionsDir,
457	        unsafe,
458	      });
459	    } else {
460	      // If stores exist but we need serviceKeyStore and it's missing, add it
461	      if (hasServiceKeyStore && !stores.serviceKeyStore) {
462	        switch (storeType) {
463	          case 'abap':
464	            stores.serviceKeyStore = new AbapServiceKeyStore(
465	              serviceKeysDir,
466	              storeLogger,
467	            );
468	            break;
469	          case 'btp':
470	            stores.serviceKeyStore = new BtpServiceKeyStore(
471	              serviceKeysDir,
472	              storeLogger,
473	            );
474	            break;
475	        }
476	        logger?.debug('Added serviceKeyStore to existing shared stores', {
477	          type: 'SERVICE_KEY_STORE_ADDED',
478	          storeKey,
479	          storeType,
480	        });
481	      }
482	    }
483	
484	    const { serviceKeyStore, sessionStore } = stores;
485	    const destination = serviceKeyDestination || brokerKey;
486	
487	    // Pre-seed session store with data from service key (without tokens) to avoid stale/absent configs
488	    if (hasServiceKeyStore && serviceKeyDestination) {
489	      try {
490	        logger?.debug('Starting session seed from service key', {
491	          type: 'SESSION_SEED_START',
492	          brokerKey,
493	          serviceKeyDestination,
494	          hasServiceKeyStore: !!serviceKeyStore,
495	          hasSessionStore: !!sessionStore,
496	        });
497	
498	        const skConn = await serviceKeyStore?.getConnectionConfig?.(
499	          serviceKeyDestination,
500	        );
501	        const skAuth = await serviceKeyStore?.getAuthorizationConfig?.(
502	          serviceKeyDestination,
503	        );
504	
505	        logger?.debug('Service key data retrieved', {
506	          type: 'SESSION_SEED_DATA_RETRIEVED',
507	          brokerKey,
508	          serviceKeyDestination,
509	          hasConnConfig: !!skConn,
510	          hasAuthConfig: !!skAuth,
511	          serviceUrl: skConn?.serviceUrl,
512	          serviceUrlLength: skConn?.serviceUrl?.length || 0,
513	        });
514	
515	        // Only seed connection config if serviceUrl is present
516	        if (skConn?.serviceUrl && sessionStore?.setConnectionConfig) {
517	          logger?.debug('Seeding connection config', {
518	            type: 'SESSION_SEED_CONN_START',
519	            brokerKey,
520	            serviceKeyDestination,
521	            serviceUrl: skConn.serviceUrl.substring(0, 50),
522	          });
523	          await sessionStore.setConnectionConfig(serviceKeyDestination, {
524	            ...skConn,
525	            authorizationToken: undefined,
526	          });
527	          logger?.debug('Session store seeded with connection config', {
528	            type: 'SESSION_SEED_CONN_SUCCESS',
529	            brokerKey,
530	            serviceKeyDestination,
531	            serviceUrl: skConn.serviceUrl.substring(0, 50),
532	          });
533	        } else if (skConn && !skConn.serviceUrl) {
534	          logger?.debug(
535	            `Service key for ${serviceKeyDestination} does not contain serviceUrl. Skipping connection config seed.`,
536	            {
537	              type: 'SESSION_SEED_SKIP_NO_SERVICE_URL',
538	              brokerKey,
539	              serviceKeyDestination,
540	            },
541	          );
542	        } else if (!skConn) {
543	          logger?.debug(
544	            `Service key store returned null connection config for ${serviceKeyDestination}`,
545	            {
546	              type: 'SESSION_SEED_NO_CONN_CONFIG',
547	              brokerKey,
548	              serviceKeyDestination,
549	            },
550	          );
551	        }
552	
553	        if (skAuth && sessionStore?.setAuthorizationConfig) {
554	          logger?.debug('Seeding authorization config', {
555	            type: 'SESSION_SEED_AUTH_START',
556	            brokerKey,
557	            serviceKeyDestination,
558	          });
559	          await sessionStore.setAuthorizationConfig(
560	            serviceKeyDestination,
561	            skAuth,
562	          );
563	          logger?.debug('Session store seeded with authorization config', {
564	            type: 'SESSION_SEED_AUTH_SUCCESS',
565	            brokerKey,
566	            serviceKeyDestination,
567	          });
568	        } else if (!skAuth) {
569	          logger?.debug(
570	            `Service key store returned null authorization config for ${serviceKeyDestination}`,
571	            {
572	              type: 'SESSION_SEED_NO_AUTH_CONFIG',
573	              brokerKey,
574	              serviceKeyDestination,
575	            },
576	          );
577	        }
578	      } catch (e) {
579	        logger?.debug('Failed to seed session store from service key', {
580	          type: 'SESSION_SEED_FAILED',
581	          brokerKey,
582	          serviceKeyDestination,
583	          error: (e as Error)?.message,
584	          stack: (e as Error)?.stack,
585	        });
586	        // Don't throw - broker will try to get serviceUrl from serviceKeyStore when needed
587	      }
588	    } else {
589	      logger?.debug('Skipping session seed', {
590	        type: 'SESSION_SEED_SKIPPED',
591	        brokerKey,
592	        hasServiceKeyStore,
593	        serviceKeyDestination,
594	      });
595	    }
596	
597	    const tokenProvider = await this.createTokenProviderForDestination(
598	      destination,
599	      storeType,
600	      sessionStore,
601	      serviceKeyStore,
602	      logger,
603	    );
604	
605	    // Create AuthBroker
606	    const authBroker = new AuthBroker(
607	      {
608	        serviceKeyStore: hasServiceKeyStore ? serviceKeyStore : undefined,
609	        sessionStore,
610	        tokenProvider,
611	      } as any,
612	      this.config.browser || 'system',
613	      brokerLogger,
614	    );
615	
616	    this.authBrokers.set(brokerKey, authBroker);
617	
618	    logger?.debug('AuthBroker created', {
619	      type: 'AUTH_BROKER_CREATED',
620	      brokerKey,
621	      hasServiceKeyStore,
622	      serviceKeyDestination,
623	      storeType,
624	    });
625	  }
626	
627	  /**
628	   * Create broker using EnvFileSessionStore directly
629	   * Used for --env=path option (Variant 2)
630	   *
631	   * EnvFileSessionStore reads connection config directly from .env file
632	   * and stores token updates in memory (doesn't modify original file)
633	   */
634	  private async createBrokerWithEnvFileStore(
635	    brokerKey: string,
636	    envFilePath: string,
637	    logger: ILogger | undefined,
638	  ): Promise<void> {
639	    // Only use specific loggers if DEBUG variables are set, no fallback
640	    const storeLogger = this.config.storeLogger;
641	    const providerLogger = this.config.providerLogger;
642	    const brokerLogger = this.config.brokerLogger;
643	    // Create EnvFileSessionStore that reads from specified .env file
644	    const sessionStore = new EnvFileSessionStore(envFilePath, storeLogger);
645	
646	    // Get auth type from .env file to determine if we need token provider
647	    const authType = sessionStore.getAuthType();
648	
649	    if (!authType) {
650	      throw new Error(
651	        `Unable to determine auth type from .env file: ${envFilePath}`,
652	      );
653	    }
654	
655	    // EnvFileSessionStore reads SAP_PASSWORD raw from disk and does NOT resolve
656	    // keychain:<service>/<account> references. For sc4sap multi-profile setups
657	    // that store passwords in the OS keychain, we must resolve the reference
658	    // here and seed the store's inMemoryUpdates so subsequent getConnectionConfig
659	    // calls return plaintext. Without this, the literal "keychain:..." string
660	    // is sent as the Basic Auth password, causing 401 → account lockout.
661	    if (authType === 'basic') {
662	      const raw = await sessionStore.getConnectionConfig(brokerKey);
663	      const rawPwd = raw?.password;
664	      if (rawPwd && rawPwd.startsWith('keychain:')) {
665	        const resolved = resolveSecret(rawPwd);
666	        await sessionStore.setConnectionConfig(brokerKey, {
667	          ...raw,
668	          password: resolved,
669	        });
670	        logger?.debug('Resolved keychain password into EnvFileSessionStore', {
671	          type: 'ENV_FILE_STORE_KEYCHAIN_RESOLVED',
672	          brokerKey,
673	          envFilePath,
674	        });
675	      }
676	    }
677	
678	    logger?.debug('Creating broker with EnvFileSessionStore', {
679	      type: 'ENV_FILE_STORE_CREATE',
680	      brokerKey,
681	      envFilePath,
682	      authType,
683	    });
684	
685	    const tokenProvider = await this.createTokenProviderForDestination(
686	      brokerKey,
687	      'abap',
688	      sessionStore,
689	      undefined,
690	      providerLogger,
691	    );
692	
693	    // Create AuthBroker with EnvFileSessionStore
694	    const authBroker = new AuthBroker(
695	      {
696	        serviceKeyStore: undefined, // No service key store for --env mode
697	        sessionStore,
698	        tokenProvider,
699	      } as any,
700	      this.config.browser || 'system',
701	      brokerLogger,
702	    );
703	
704	    this.authBrokers.set(brokerKey, authBroker);
705	
706	    logger?.debug('AuthBroker created with EnvFileSessionStore', {
707	      type: 'AUTH_BROKER_CREATED_ENV_FILE',
708	      brokerKey,
709	      envFilePath,
710	      authType,
711	    });
712	  }
713	
714	  /**
715	   * Load .env file and populate session store with connection config
716	   * @param envFilePath Path to .env file
717	   * @param destination Destination name (usually 'default')
718	   * @param broker AuthBroker instance
719	   * @param logger Logger instance
720	   * @returns Auth type from .env file ('basic' or 'jwt')
721	   */
722	  private async loadEnvFileIntoSessionStore(
723	    envFilePath: string,
724	    destination: string,
725	    broker: AuthBroker,
726	    logger: ILogger | undefined,
727	  ): Promise<'basic' | 'jwt'> {
728	    if (!fs.existsSync(envFilePath)) {
729	      throw new Error(`.env file not found: ${envFilePath}`);
730	    }
731	
732	    logger?.debug('Loading .env file into session store', {
733	      type: 'ENV_LOAD_START',
734	      envFilePath,
735	      destination,
736	    });
737	
738	    // Parse .env file
739	    const envContent = fs.readFileSync(envFilePath, 'utf8');
740	    const envVars: Record<string, string> = {};
741	
742	    for (const line of envContent.split(/\r?\n/)) {
743	      const trimmed = line.trim();
744	      if (!trimmed || trimmed.startsWith('#')) continue;
745	
746	      const eqIndex = trimmed.indexOf('=');
747	      if (eqIndex === -1) continue;
748	
749	      const key = trimmed.substring(0, eqIndex).trim();
750	      let value = trimmed.substring(eqIndex + 1);
751	
752	      // Inline comments are intentionally not supported.
753	      // A '#' is treated as comment only when it starts the line.
754	      value = value.trim();
755	
756	      // Remove quotes
757	      value = value.replace(/^["']+|["']+$/g, '').trim();
758	
759	      if (key) {
760	        envVars[key] = value;
761	      }
762	    }
763	
764	    // Validate required fields
765	    if (!envVars.SAP_URL) {
766	      throw new Error('.env file missing SAP_URL');
767	    }
768	
769	    // Build connection config from .env
770	    const connectionConfig: any = {
771	      serviceUrl: envVars.SAP_URL,
772	      sapClient: envVars.SAP_CLIENT,
773	    };
774	
775	    // Check auth type: auto-detect JWT if SAP_JWT_TOKEN present, otherwise use SAP_AUTH_TYPE (default: basic)
776	    const rawAuthType = (envVars.SAP_AUTH_TYPE || 'basic').trim().toLowerCase();
777	    const authType: 'basic' | 'jwt' = envVars.SAP_JWT_TOKEN
778	      ? 'jwt'
779	      : rawAuthType === 'jwt'
780	        ? 'jwt'
781	        : 'basic';
782	    connectionConfig.authType = authType;
783	
784	    if (authType === 'basic') {
785	      if (!envVars.SAP_USERNAME || !envVars.SAP_PASSWORD) {
786	        throw new Error(
787	          '.env file missing SAP_USERNAME or SAP_PASSWORD for basic auth',
788	        );
789	      }
790	      connectionConfig.username = envVars.SAP_USERNAME;
791	      // Resolve keychain:<service>/<account> → plaintext before seeding session
792	      // store. Without this, the literal reference string is used as the Basic
793	      // Auth password, causing 401 → account lockout.
794	      connectionConfig.password = resolveSecret(envVars.SAP_PASSWORD);
795	    } else if (authType === 'jwt') {
796	      if (!envVars.SAP_JWT_TOKEN) {
797	        throw new Error('.env file missing SAP_JWT_TOKEN for JWT auth');
798	      }
799	      connectionConfig.authorizationToken = envVars.SAP_JWT_TOKEN;
800	      // Also store refresh token if available
801	      if (envVars.SAP_REFRESH_TOKEN) {
802	        connectionConfig.refreshToken = envVars.SAP_REFRESH_TOKEN;
803	      }
804	    }
805	
806	    // Store in session store via broker's session store
807	    const sessionStore = (broker as any).sessionStore as ISessionStore;
808	    if (sessionStore?.setConnectionConfig) {
809	      await sessionStore.setConnectionConfig(destination, connectionConfig);
810	      logger?.debug('.env file loaded into session store', {
811	        type: 'ENV_LOAD_SUCCESS',
812	        destination,
813	        serviceUrl: connectionConfig.serviceUrl,
814	        authType: connectionConfig.authType,
815	      });
816	    } else {
817	      throw new Error('Session store does not support setConnectionConfig');
818	    }
819	
820	    if (authType === 'jwt') {
821	      const hasUaaConfig =
822	        envVars.SAP_UAA_URL &&
823	        envVars.SAP_UAA_CLIENT_ID &&
824	        envVars.SAP_UAA_CLIENT_SECRET;
825	      if (hasUaaConfig && sessionStore?.setAuthorizationConfig) {
826	        await sessionStore.setAuthorizationConfig(destination, {
827	          uaaUrl: envVars.SAP_UAA_URL,
828	          uaaClientId: envVars.SAP_UAA_CLIENT_ID,
829	          uaaClientSecret: envVars.SAP_UAA_CLIENT_SECRET,
830	          refreshToken: envVars.SAP_REFRESH_TOKEN,
831	        });
832	      }
833	    }
834	
835	    return authType;
836	  }
837	
838	  private async createTokenProviderForDestination(
839	    destination: string,
840	    storeType: 'abap' | 'btp',
841	    sessionStore: ISessionStore,
842	    serviceKeyStore: IServiceKeyStore | undefined,
843	    logger: ILogger | undefined,
844	  ): Promise<ITokenProvider> {
845	    // Use providerLogger only if DEBUG_PROVIDER is set, otherwise undefined (no logging)
846	    const providerLogger = this.config.providerLogger;
847	    let authConfig: IAuthorizationConfig | null = null;
848	    let connConfig: IConnectionConfig | null = null;
849	
850	    try {
851	      connConfig = await sessionStore.getConnectionConfig(destination);
852	    } catch (error) {
853	      logger?.debug('Failed to read connection config for token provider', {
854	        destination,
855	        error: error instanceof Error ? error.message : String(error),
856	      });
857	    }
858	
859	    try {
860	      authConfig = await sessionStore.getAuthorizationConfig(destination);
861	    } catch (error) {
862	      logger?.debug('Failed to read auth config from session store', {
863	        destination,
864	        error: error instanceof Error ? error.message : String(error),
865	      });
866	    }
867	
868	    if (!authConfig && serviceKeyStore?.getAuthorizationConfig) {
869	      try {
870	        authConfig = await serviceKeyStore.getAuthorizationConfig(destination);
871	      } catch (error) {
872	        logger?.debug('Failed to read auth config from service key store', {
873	          destination,
874	          error: error instanceof Error ? error.message : String(error),
875	        });
876	      }
877	    }
878	
879	    if (!authConfig) {
880	      return this.wrapLegacyTokenProvider({
881	        getTokens: async (): Promise<ITokenResult> => {
882	          throw new Error(
883	            `Authorization config is required for destination "${destination}". Provide a service key or session with UAA credentials.`,
884	          );
885	        },
886	      });
887	    }
888	
889	    const providerConfig = {
890	      uaaUrl: authConfig.uaaUrl,
891	      clientId: authConfig.uaaClientId,
892	      clientSecret: authConfig.uaaClientSecret,
893	      refreshToken: authConfig.refreshToken,
894	      accessToken: connConfig?.authorizationToken,
895	      browser: this.config.browser || 'system',
896	      redirectPort: this.config.browserAuthPort,
897	      logger: providerLogger,
898	    };
899	
900	    // For mcp-abap-adt, AuthorizationCodeProvider is the only provider used
901	    // Both 'abap' and 'btp' store types use AuthorizationCodeProvider
902	    if (storeType === 'btp' || storeType === 'abap') {
903	      return this.wrapLegacyTokenProvider(
904	        new AuthorizationCodeProvider(providerConfig),
905	      );
906	    }
907	
908	    // This should never happen, but throw error for safety
909	    throw new Error(
910	      `Unsupported store type "${storeType}" for destination "${destination}". Only 'abap' and 'btp' are supported.`,
911	    );
912	  }
913	
914	  private wrapLegacyTokenProvider(
915	    tokenProvider: ITokenProvider,
916	  ): ITokenProvider & {
917	    getConnectionConfig?: (
918	      _authConfig: unknown,
919	      _options?: unknown,
920	    ) => Promise<{
921	      connectionConfig: { authorizationToken?: string };
922	      refreshToken?: string;
923	    }>;
924	  } {
925	    if (typeof tokenProvider.getTokens !== 'function') {
926	      throw new Error('AuthBrokerFactory: tokenProvider.getTokens is required');
927	    }
928	    if (typeof (tokenProvider as any).getConnectionConfig === 'function') {
929	      return tokenProvider as any;
930	    }
931	
932	    const getTokens = tokenProvider.getTokens.bind(tokenProvider);
933	
934	    return {
935	      getTokens,
936	      getConnectionConfig: async () => {
937	        const tokenResult = await getTokens();
938	        return {
939	          connectionConfig: {
940	            authorizationToken: tokenResult.authorizationToken,
941	          },
942	          refreshToken: tokenResult.refreshToken,
943	        };
944	      },
945	    };
946	  }
947	
948	  /**
949	   * Get existing AuthBroker without creating new one
950	   */
951	  getAuthBroker(destination?: string): AuthBroker | undefined {
952	    if (!destination) {
953	      return this.getDefaultBroker();
954	    }
955	    return this.authBrokers.get(destination);
956	  }
957	
958	  /**
959	   * Clear all AuthBroker instances
960	   */
961	  clear(): void {
962	    this.authBrokers.clear();
963	    this.sharedStores.clear();
964	    this.defaultBrokerInitialized = false;
965	  }
966	}
